import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"ERB 的复合语句","description":"","frontmatter":{},"headers":[],"relativePath":"reference/ERB_Compound_Statements.md","filePath":"reference/ERB_Compound_Statements.md"}`),a={name:`reference/ERB_Compound_Statements.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="erb-的复合语句" tabindex="-1">ERB 的复合语句 <a class="header-anchor" href="#erb-的复合语句" aria-label="Permalink to “ERB 的复合语句”">​</a></h1><p><strong>复合语句</strong>会跨越多行，控制程序“分支”或“重复”。它们都成对出现，写的时候一定要注意闭合。教程版见<a href="./../guide/tutorials/Compound_Statement.html">复合语句</a>。</p><h2 id="条件分支-if" tabindex="-1">条件分支：IF <a class="header-anchor" href="#条件分支-if" aria-label="Permalink to “条件分支：IF”">​</a></h2><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#C586C0;">IF</span><span style="color:#9CDCFE;"> 条件</span></span>
<span class="line"><span style="color:#6A9955;">  ; 条件成立时执行</span></span>
<span class="line"><span style="color:#C586C0;">ELSEIF</span><span style="color:#9CDCFE;"> 另一条件</span></span>
<span class="line"><span style="color:#6A9955;">  ; 前面的条件都不成立、且此条成立时执行</span></span>
<span class="line"><span style="color:#C586C0;">ELSE</span></span>
<span class="line"><span style="color:#6A9955;">  ; 都不成立时执行</span></span>
<span class="line"><span style="color:#C586C0;">ENDIF</span></span></code></pre></div><ul><li><code>ELSEIF</code> 可以有多个，也可以没有；</li><li><code>ELSE</code> 可以没有；</li><li><code>ENDIF</code> 必须有。</li></ul><h2 id="计数循环-repeat" tabindex="-1">计数循环：REPEAT <a class="header-anchor" href="#计数循环-repeat" aria-label="Permalink to “计数循环：REPEAT”">​</a></h2><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#C586C0;">REPEAT</span><span style="color:#9CDCFE;"> 次数</span></span>
<span class="line"><span style="color:#6A9955;">  ; 重复执行</span></span>
<span class="line"><span style="color:#C586C0;">REND</span></span></code></pre></div><p>计数器是内置变量 <code>COUNT</code>，<strong>从 0 开始</strong>。</p><h2 id="增强循环-for" tabindex="-1">增强循环：FOR <a class="header-anchor" href="#增强循环-for" aria-label="Permalink to “增强循环：FOR”">​</a></h2><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#C586C0;">FOR</span><span style="color:#9CDCFE;"> 变量</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">初始值</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">终止值</span><span style="color:#E6E6E6;">{, </span><span style="color:#9CDCFE;">步长</span><span style="color:#E6E6E6;">}</span></span>
<span class="line"><span style="color:#6A9955;">  ; 重复执行</span></span>
<span class="line"><span style="color:#C586C0;">NEXT</span></span></code></pre></div><ul><li><code>变量</code> 从 <code>初始值</code> 开始，每轮加 <code>步长</code>（默认 1），直到达到 <code>终止值</code> 之前停止；</li><li>终止值不包含在内；</li><li>循环变量不能与其他嵌套循环重名。</li></ul><h2 id="条件循环-while" tabindex="-1">条件循环：WHILE <a class="header-anchor" href="#条件循环-while" aria-label="Permalink to “条件循环：WHILE”">​</a></h2><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#C586C0;">WHILE</span><span style="color:#9CDCFE;"> 条件</span></span>
<span class="line"><span style="color:#6A9955;">  ; 条件成立时重复</span></span>
<span class="line"><span style="color:#C586C0;">WEND</span></span></code></pre></div><h2 id="后置条件循环-do" tabindex="-1">后置条件循环：DO <a class="header-anchor" href="#后置条件循环-do" aria-label="Permalink to “后置条件循环：DO”">​</a></h2><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#C586C0;">DO</span></span>
<span class="line"><span style="color:#6A9955;">  ; 至少执行一次</span></span>
<span class="line"><span style="color:#C586C0;">LOOP</span><span style="color:#9CDCFE;"> 条件</span></span></code></pre></div><p>与 <code>WHILE</code> 不同，<code>DO…LOOP</code> 至少执行一次。</p><h2 id="多路分支-selectcase" tabindex="-1">多路分支：SELECTCASE <a class="header-anchor" href="#多路分支-selectcase" aria-label="Permalink to “多路分支：SELECTCASE”">​</a></h2><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#C586C0;">SELECTCASE</span><span style="color:#9CDCFE;"> 表达式</span></span>
<span class="line"><span style="color:#C586C0;">  CASE</span><span style="color:#9CDCFE;"> 值</span></span>
<span class="line"><span style="color:#6A9955;">    ; 匹配时执行</span></span>
<span class="line"><span style="color:#C586C0;">  CASE</span><span style="color:#9CDCFE;"> 值1</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">值2</span></span>
<span class="line"><span style="color:#6A9955;">    ; 匹配其中任意一个时执行</span></span>
<span class="line"><span style="color:#C586C0;">  CASE</span><span style="color:#9CDCFE;"> 起始值</span><span style="color:#569CD6;"> TO</span><span style="color:#9CDCFE;"> 终止值</span></span>
<span class="line"><span style="color:#6A9955;">    ; 在范围内时执行</span></span>
<span class="line"><span style="color:#C586C0;">  CASE</span><span style="color:#569CD6;"> IS</span><span style="color:#D4D4D4;"> &lt;=</span><span style="color:#9CDCFE;"> 值</span></span>
<span class="line"><span style="color:#6A9955;">    ; 满足比较时执行</span></span>
<span class="line"><span style="color:#C586C0;">  CASEELSE</span></span>
<span class="line"><span style="color:#6A9955;">    ; 都不匹配时执行</span></span>
<span class="line"><span style="color:#C586C0;">ENDSELECT</span></span></code></pre></div><p><code>CASE</code> 的条件从左到右依次判断，命中即停。</p><h2 id="循环控制" tabindex="-1">循环控制 <a class="header-anchor" href="#循环控制" aria-label="Permalink to “循环控制”">​</a></h2><table tabindex="0"><thead><tr><th>语句</th><th>作用</th></tr></thead><tbody><tr><td><code>BREAK</code></td><td>立即跳出当前循环</td></tr><tr><td><code>CONTINUE</code></td><td>跳过本轮剩余内容，进入下一轮</td></tr></tbody></table><h2 id="异常分支-tryc-catch-endcatch" tabindex="-1">异常分支：TRYC / CATCH / ENDCATCH <a class="header-anchor" href="#异常分支-tryc-catch-endcatch" aria-label="Permalink to “异常分支：TRYC / CATCH / ENDCATCH”">​</a></h2><p>用于捕获“函数不存在”的情况：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#C586C0;">TRYCCALL</span><span style="color:#DCDCAA;"> 可能不存在的函数</span></span>
<span class="line"><span style="color:#6A9955;">  ; 函数存在时，调用后执行</span></span>
<span class="line"><span style="color:#C586C0;">CATCH</span></span>
<span class="line"><span style="color:#6A9955;">  ; 函数不存在时执行</span></span>
<span class="line"><span style="color:#C586C0;">ENDCATCH</span></span></code></pre></div><p>相关命令还有 <code>TRYCJUMP</code>、<code>TRYCGOTO</code>、<code>TRYCJUMPFORM</code> 等。</p><h2 id="函数列表调用-trycalllist-func-endfunc" tabindex="-1">函数列表调用：TRYCALLLIST / FUNC / ENDFUNC <a class="header-anchor" href="#函数列表调用-trycalllist-func-endfunc" aria-label="Permalink to “函数列表调用：TRYCALLLIST / FUNC / ENDFUNC”">​</a></h2><p>依次尝试多个函数，调用最先找到的那个：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#C586C0;">TRYCALLLIST</span></span>
<span class="line"><span style="color:#C586C0;">  FUNC</span><span style="color:#E6E6E6;"> 函数1</span></span>
<span class="line"><span style="color:#C586C0;">  FUNC</span><span style="color:#E6E6E6;"> 函数2</span></span>
<span class="line"><span style="color:#C586C0;">ENDFUNC</span></span></code></pre></div><p>对应地还有 <code>TRYJUMPLIST</code>、<code>TRYGOTOLIST</code>。</p><h2 id="嵌套与注意事项" tabindex="-1">嵌套与注意事项 <a class="header-anchor" href="#嵌套与注意事项" aria-label="Permalink to “嵌套与注意事项”">​</a></h2><ul><li>复合语句可以任意嵌套，但<strong>每一层都要完整闭合</strong>；</li><li>漏写 <code>ENDIF</code> / <code>REND</code> / <code>NEXT</code> / <code>WEND</code> 会直接报错；</li><li><code>REPEAT</code> 嵌套时若使用不当可能出现无限循环，注意计数器；</li><li>建议每层缩进两个空格，避免“找不到配对”。</li></ul><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to “相关链接”">​</a></h2><ul><li><a href="./../guide/tutorials/Compound_Statement.html">复合语句</a>（教程）</li><li><a href="./../translation/Command.html#循环·分支语法">循环·分支语法</a>（命令详解）</li><li><a href="./../translation/Command.html#call·jump·goto系">CALL·JUMP·GOTO 系</a></li><li><a href="./ERB_Statements.html">ERB 的语句</a></li></ul>`,33)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};